SELECT routine_name, data_type FROM information_schema.routines WHERE routine_schema = 'app' AND (routine_name ILIKE '%overlay%' OR routine_name ILIKE '%render%' OR routine_name ILIKE '%watermark%' OR routine_name ILIKE '%share%' OR routine_name ILIKE '%live%' OR routine_name ILIKE '%spectator%' OR routine_name ILIKE '%stream%' OR routine_name ILIKE '%replay%' OR routine_name ILIKE '%clip%' OR routine_name ILIKE '%free_video%' OR routine_name ILIKE '%video_share%' OR routine_name ILIKE '%recording%') ORDER BY routine_name;
